def camel_to_snake(s: str) -> str:
    """Convert camelCase or PascalCase to snake_case. Consecutive capitals stay together (HTTPServer -> http_server)."""
    if not s:
        return ''
    result = []
    prev_lower = False
    for i, ch in enumerate(s):
        if ch.isupper():
            # Determine if we need underscore
            if i > 0 and (prev_lower or (i+1 < len(s) and s[i+1].islower())):
                result.append('_')
            result.append(ch.lower())
            prev_lower = False
        else:
            result.append(ch)
            prev_lower = True
    return ''.join(result)

